package com.nexusdrive.metadata.repository;import com.nexusdrive.metadata.entity.FileMetadata;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface FileMetadataRepository extends JpaRepository<FileMetadata,UUID>,JpaSpecificationExecutor<FileMetadata>{Optional<FileMetadata> findFirstByContentHashAndStatus(String h,FileMetadata.Status s);Optional<FileMetadata> findByIdAndOwnerId(UUID i,UUID o);List<FileMetadata> findByOwnerIdAndFolderIdAndStatus(UUID o,UUID f,FileMetadata.Status s);List<FileMetadata> findTop100ByStatusOrderByUpdatedAtAsc(FileMetadata.Status s);@Query("select f from FileMetadata f where f.id=:id and (f.ownerId=:u or exists(select p.id from SharePermission p where p.file=f and (p.sharedWithUserId=:u or p.visibility=com.nexusdrive.common.enums.ShareVisibility.PUBLIC)))")Optional<FileMetadata> findAccessible(@Param("id")UUID id,@Param("u")UUID user);}
